//! 由 `reference/gen/structvec.c`（cubiomes `finders.c` 参考实现）生成的
//! golden 测试。数据由 `reference/gen/gen_struct_tests.py` 转换，请勿手工编辑。
//!
//! f32 按位模式比较；`mc` 列为 cubiomes 的 `MCVersion` 枚举值
//! （10 = 1.7 … 28 = 1.21），由 [`mc`] 映射为 [`McVersion`]。
#![allow(clippy::type_complexity)] // 大元组 golden 表，保持数据直写

use super::config::get_config;
use super::region::{
    get_end_islands, get_mineshafts, get_population_seed, get_structure_pos, is_slime_chunk, Pos,
};
use super::spawn::estimate_spawn;
use super::stronghold::{init_first_stronghold, StrongholdIter};
use super::variant::get_variant;
use super::viability::{is_viable_feature_biome, is_viable_structure_pos};
use super::StructureType;
use crate::generator::Generator;
use crate::version::{Dimension, McVersion};

fn mc(v: u32) -> McVersion {
    match v {
        10 => McVersion::V1_7,
        11 => McVersion::V1_8,
        12 => McVersion::V1_9,
        13 => McVersion::V1_10,
        14 => McVersion::V1_11,
        15 => McVersion::V1_12,
        16 => McVersion::V1_13,
        17 => McVersion::V1_14,
        18 => McVersion::V1_15,
        19 => McVersion::V1_16_1,
        20 => McVersion::V1_16,
        21 => McVersion::V1_17,
        22 => McVersion::V1_18,
        23 => McVersion::V1_19_2,
        24 => McVersion::V1_19,
        25 => McVersion::V1_20,
        26 => McVersion::V1_21_1,
        27 => McVersion::V1_21_3,
        28 => McVersion::V1_21,
        _ => panic!("bad mc"),
    }
}

fn dim(d: i32) -> Dimension {
    match d {
        -1 => Dimension::Nether,
        0 => Dimension::Overworld,
        1 => Dimension::End,
        _ => panic!("bad dim"),
    }
}

