#[test]
fn structure_config_matches_c() {
    for &(st, v, ret, salt, rs, cr, sst, d, rar) in CONFIG_CASES {
        let stype = StructureType::from_u8(st).unwrap();
        match get_config(stype, mc(v)) {
            None => assert!(!ret, "stype {st} mc {v}: C 有配置而 Rust 无"),
            Some(c) => {
                assert!(ret, "stype {st} mc {v}: C 无配置而 Rust 有");
                assert_eq!(c.salt, salt, "stype {st} mc {v} salt");
                assert_eq!(c.region_size, rs, "stype {st} mc {v} region_size");
                assert_eq!(c.chunk_range, cr, "stype {st} mc {v} chunk_range");
                assert_eq!(c.struct_type as i32, sst, "stype {st} mc {v} struct_type");
                assert_eq!(c.dim, d, "stype {st} mc {v} dim");
                assert_eq!(c.rarity.to_bits(), rar, "stype {st} mc {v} rarity");
            }
        }
    }
}

