#[test]
fn structure_pos_matches_c() {
    for &(st, v, seed, rx, rz, ret, x, z) in STRUCTPOS_CASES {
        let stype = StructureType::from_u8(st).unwrap();
        let got = get_structure_pos(stype, mc(v), seed as u64, rx, rz);
        assert_eq!(
            got,
            if ret { Some(Pos { x, z }) } else { None },
            "stype {st} mc {v} seed {seed} region ({rx}, {rz})"
        );
    }
}

