#[test]
fn mineshafts_match_c() {
    for &(v, seed, cx, cz, n, x0, z0) in MINESHAFT_CASES {
        let mut buf = [Pos::default(); 2];
        let got = get_mineshafts(mc(v), seed as u64, cx, cz, cx, cz, Some(&mut buf));
        assert_eq!(got, n, "mc {v} seed {seed} chunk ({cx}, {cz}) n");
        if n > 0 {
            assert_eq!(buf[0], Pos { x: x0, z: z0 }, "mc {v} seed {seed} chunk ({cx}, {cz}) pos");
        }
    }
}

