#[test]
fn population_seed_matches_c() {
    for &(v, seed, x, z, expect) in POPSEED_CASES {
        assert_eq!(
            get_population_seed(mc(v), seed as u64, x, z),
            expect,
            "mc {v} seed {seed} ({x}, {z})"
        );
    }
}

