#[test]
fn strongholds_match_c() {
    // 数据按 (mc, seed, idx) 顺序排列：idx=-1 行建立状态，后续行依次 next。
    let mut iter: Option<StrongholdIter> = None;
    let mut genr: Option<Generator> = None;
    for &(v, seed, idx, ret, px, pz, nx, nz) in STRONGHOLD_CASES {
        if idx == -1 {
            let first = init_first_stronghold(mc(v), seed as u64);
            assert_eq!(first, Pos { x: px, z: pz }, "init mc {v} seed {seed}");
            let it = StrongholdIter::new(mc(v), seed as u64);
            assert_eq!(
                it.nextapprox,
                Pos { x: nx, z: nz },
                "init nextapprox mc {v} seed {seed}"
            );
            iter = Some(it);
            genr = Some(Generator::new(mc(v)).with_seed(Dimension::Overworld, seed as u64));
        } else {
            let it = iter.as_mut().unwrap();
            let got_ret = it.next(genr.as_ref());
            assert_eq!(got_ret, ret, "mc {v} seed {seed} idx {idx} ret");
            assert_eq!(it.pos, Pos { x: px, z: pz }, "mc {v} seed {seed} idx {idx} pos");
            assert_eq!(
                it.nextapprox,
                Pos { x: nx, z: nz },
                "mc {v} seed {seed} idx {idx} nextapprox"
            );
        }
    }
}

