#[test]
fn estimate_spawn_matches_c() {
    for &(v, seed, x, z) in SPAWN_CASES {
        let g = Generator::new(mc(v)).with_seed(Dimension::Overworld, seed as u64);
        assert_eq!(
            estimate_spawn(&g),
            Pos { x, z },
            "mc {v} seed {seed}"
        );
    }
}

