#[test]
fn variants_match_c() {
    for &(st, v, seed, x, z, biome, ret, abandoned, giant, underground, airpocket, basement,
        cracked, size, start, vbiome, rotation, mirror, vx, vy, vz, sx, sy, sz) in VARIANT_CASES
    {
        let stype = StructureType::from_u8(st).unwrap();
        let got = get_variant(stype, mc(v), seed as u64, x, z, biome);
        let ctx = format!("stype {st} mc {v} seed {seed} ({x}, {z}) biome {biome}");
        if !ret {
            assert!(got.is_none(), "{ctx}: C 返回 0 而 Rust 为 Some");
            continue;
        }
        let sv = got.unwrap_or_else(|| panic!("{ctx}: C 返回 1 而 Rust 为 None"));
        assert_eq!(sv.abandoned, abandoned, "{ctx} abandoned");
        assert_eq!(sv.giant, giant, "{ctx} giant");
        assert_eq!(sv.underground, underground, "{ctx} underground");
        assert_eq!(sv.airpocket, airpocket, "{ctx} airpocket");
        assert_eq!(sv.basement, basement, "{ctx} basement");
        assert_eq!(sv.cracked, cracked, "{ctx} cracked");
        assert_eq!(sv.size, size, "{ctx} size");
        assert_eq!(sv.start, start, "{ctx} start");
        assert_eq!(sv.biome, vbiome, "{ctx} biome");
        assert_eq!(sv.rotation, rotation, "{ctx} rotation");
        assert_eq!(sv.mirror, mirror, "{ctx} mirror");
        assert_eq!((sv.x, sv.y, sv.z), (vx, vy, vz), "{ctx} pos");
        assert_eq!((sv.sx, sv.sy, sv.sz), (sx, sy, sz), "{ctx} size3");
    }
}

