#[test]
fn viable_structure_pos_matches_c() {
    // 汇集全部失配后再断言，避免逐条修案例
    let mut bad = String::new();
    for &(st, v, seed, x, z, ret) in VIABLE_CASES {
        let stype = StructureType::from_u8(st).unwrap();
        let conf = get_config(stype, mc(v)).unwrap();
        let g = Generator::new(mc(v)).with_seed(dim(conf.dim as i32), seed as u64);
        let got = is_viable_structure_pos(stype, &g, x, z, 0);
        if got != ret {
            bad.push_str(&format!(
                "stype {st} mc {v} seed {seed} ({x}, {z}): rust {got} c {ret}
"
            ));
        }
    }
    assert!(bad.is_empty(), "
{bad}");
}

