#[test]
fn viable_feature_biome_matches_c() {
    for &(st, v, bid, ret) in FEATBIOME_CASES {
        let stype = StructureType::from_u8(st).unwrap();
        assert_eq!(
            is_viable_feature_biome(mc(v), stype, bid),
            ret,
            "stype {st} mc {v} biome {bid}"
        );
    }
}

